    const workSelector=p.permissions?.manage&&ui&&Number.isInteger(intelligence?.stage?.version)?'<label class="pm-work-stage">项目工作阶段：<select data-pm-work-stage aria-label="更正项目工作阶段">'+(!work.key?'<option value="">待确认</option>':'')+ui.STAGES.map(x=>'<option value="'+x.key+'" '+(x.key===work.key?'selected':'')+'>'+esc(x.label)+'</option>').join('')+'</select></label>':'<p class="pm-work-stage">项目工作阶段：<b>'+esc(work.label)+'</b></p>';
    const head='<div class="pm-detail-head"><div><span class="pm-eyebrow">项目工作区</span><h2>'+esc(p.name||"未命名项目")+'</h2><p>'+esc(displayType(p.type))+' · '+esc(p.location||"位置待补")+' · 负责人 '+esc(p.owner||"待指定")+'</p>'+workSelector+(intelligence?.stage?.legacyConflict?'<p class="pm-hint">历史阶段记录存在差异，请由负责人核对工作阶段。</p>':'')+'</div><div class="pm-detail-head-actions">'+(action?'<button type="button" class="btn pm-primary-action" '+actionAttr+'>'+esc(action.label)+'</button>':'')+management+'</div></div>'+(ui?ui.stageNavigation(view==="stages"?viewStageKey:null,work.key):'')+nav;
    if(view==="versions")return head+reportVersionsHtml(p);
