    if(view==="stages")return head+(viewStageKey&&ui?ui.stageWorkspace(viewStageKey,{brain,brainError:error,intelligence,intelligenceError,ops,opsError}):intelligenceHtml(intelligence,intelligenceError))+(['implementation','post_investment'].includes(viewStageKey)?'<section class="pm-detail-section" data-pm-lifecycle-host="'+(viewStageKey==='implementation'?'plan':'operations')+'"><p role="status">正在读取'+(viewStageKey==='implementation'?'实施计划':'投后管理')+'…</p></section>':'')+requirementsHtml;
    if(view==="facts")return head+requirementsHtml+brainHtml(brain,error);
    if(view==="files")return head+workspaceHtml+requirementsHtml;
    if(["actions","scenarios","acceptance"].includes(view))return head+opsHtml(ops,opsError,view);
    if(view==="decisions")return head+workspaceHtml+brainHtml(brain,error,"decisions");
    if(view!=="overview")return head+workspaceHtml;
    return head
      +'<div class="pm-phase"><div><b>生命周期：'+esc(intelligence?.stage?.label||p.stage)+'</b><span>'+(intelligence?.progress?.configured?'项目真实进度 '+Number(intelligence.progress.value||0)+'%':'项目真实进度待配置')+'</span></div><i><em style="width:'+(intelligence?.progress?.configured?Number(intelligence.progress.value||0):0)+'%"></em></i></div>'
      +'<div class="pm-kpis"><div><b>'+esc(work.label)+'</b><span>项目工作阶段</span></div><div><b>'+esc(p.materials??"—")+'</b><span>项目资料</span></div><div><b>'+esc(intelligence?.kpis?.overdueTaskCount??"—")+'</b><span>逾期任务</span></div><div><b>'+esc(intelligence?.kpis?.pendingDecisionCount??"—")+'</b><span>待处理决策</span></div></div>'
      +'<div class="pm-overview-links"><button data-pw-view="stages"><b>推进项目</b><span>阶段门、里程碑与交付计划 →</span></button><button data-pw-view="versions"><b>查看成果</b><span>当前报告与历史版本 →</span></button><button data-pw-view="actions"><b>跟进行动</b><span>会议、待办与风险台账 →</span></button></div>'
