    async function load(){try{const r=await fetch("/api/projects",{headers:headers()}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||"加载失败");projects=d.list||[];render();}catch(e){listEl.hidden=false;detailEl.hidden=true;listEl.innerHTML='<div class="pm-detail-empty"><b>项目索引加载失败</b><span>'+esc(e.message)+'</span><button class="ub-btn" id="pmRetryList">重试加载项目</button></div>';listEl.querySelector("#pmRetryList").onclick=load;}}
